const results = [];
for (const item of $input.all()) {
  const url = item.json.source_url;
  let sourceType = '';
  if (url.includes('youtube.com') || url.includes('youtu.be')) sourceType = 'youtube';
  else if (url.includes('instagram.com/reel') || url.includes('instagram.com/p/')) sourceType = 'instagram';

  if (!sourceType) {
    results.push({ json: { source_url: url, source_type: 'unknown', video_id: '', title: 'ERROR: Unsupported URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_urls: [] } });
    continue;
  }

  if (sourceType === 'youtube') {
    let vid = '';
    if (url.includes('v=')) vid = url.split('v=')[1].split('&')[0];
    else if (url.includes('youtu.be/')) vid = url.split('youtu.be/')[1].split('?')[0];
    else if (url.includes('/shorts/')) vid = url.split('/shorts/')[1].split('?')[0];
    if (!vid) { results.push({ json: { source_url: url, source_type: 'youtube', video_id: '', title: 'ERROR: Invalid YouTube URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_urls: [] } }); continue; }

    let title = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.youtube.com/oembed?format=json&url=https://www.youtube.com/watch?v=' + vid });
      title = (typeof r === 'string' ? JSON.parse(r) : r).title || '';
    } catch (e) { title = 'Untitled Video'; }

    let transcript = ''; let duration_seconds = 0;
    let videoStreamUrls = [];

    const clients = [
      { clientName: 'ANDROID', clientVersion: '19.09.37' },
      { clientName: 'IOS', clientVersion: '19.09.3' },
      { clientName: 'WEB', clientVersion: '2.20240313.00.00' }
    ];

    for (const client of clients) {
      try {
        const playerResp = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://www.youtube.com/youtubei/v1/player?prettyPrint=false',
          headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
          body: JSON.stringify({ videoId: vid, context: { client: { ...client, hl: 'en' } } })
        });
        const pd = typeof playerResp === 'string' ? JSON.parse(playerResp) : playerResp;
        if (!duration_seconds) duration_seconds = parseInt(pd?.videoDetails?.lengthSeconds || '0', 10);

        const formats = [...(pd?.streamingData?.formats || []), ...(pd?.streamingData?.adaptiveFormats || [])];
        for (const f of formats) {
          if (f.url && f.mimeType && f.mimeType.includes('video/mp4')) {
            videoStreamUrls.push({ url: f.url, itag: f.itag, quality: f.qualityLabel || f.quality || '', width: f.width || 0 });
          }
        }

        if (!transcript) {
          const tracks = pd?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
          if (tracks && tracks.length > 0) {
            const t = tracks.find(t => t.languageCode === 'en') || tracks[0];
            const caps = await this.helpers.httpRequest({ method: 'GET', url: t.baseUrl + '&fmt=json3' });
            const cd = typeof caps === 'string' ? JSON.parse(caps) : caps;
            transcript = (cd.events || []).filter(e => e.segs).map(e => e.segs.map(s => s.utf8).join('')).join(' ').replace(/\s+/g, ' ').trim();
          }
          if (!transcript) { const desc = pd?.videoDetails?.shortDescription; if (desc && desc.length > 10) transcript = desc; }
        }

        if (videoStreamUrls.length > 0) break;
      } catch (e) { /* try next client */ }
    }

    if (!transcript) transcript = 'No transcript available.';
    videoStreamUrls.sort((a, b) => (a.width || 9999) - (b.width || 9999));

    results.push({ json: { source_url: url, source_type: 'youtube', video_id: vid, title, transcript, duration_seconds, aspect_ratio: url.includes('/shorts/') ? '9:16' : '16:9', video_stream_urls: videoStreamUrls } });
  }

  if (sourceType === 'instagram') {
    const reelMatch = url.match(/instagram\.com\/(?:reel|reels|p)\/([A-Za-z0-9_-]+)/);
    const shortcode = reelMatch ? reelMatch[1] : '';
    if (!shortcode) { results.push({ json: { source_url: url, source_type: 'instagram', video_id: '', title: 'ERROR: Invalid Instagram URL', transcript: '', duration_seconds: 0, aspect_ratio: '9:16', video_stream_urls: [] } }); continue; }
    let title = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.instagram.com/oembed/?url=' + encodeURIComponent(url) + '&format=json', headers: { 'User-Agent': 'Mozilla/5.0' } });
      const d = typeof r === 'string' ? JSON.parse(r) : r;
      title = d.title || (d.author_name ? 'Instagram Reel by ' + d.author_name : '');
    } catch (e) {}
    if (!title) title = 'Instagram Reel ' + shortcode;
    results.push({ json: { source_url: url, source_type: 'instagram', video_id: shortcode, title, transcript: title, duration_seconds: 0, aspect_ratio: '9:16', video_stream_urls: [] } });
  }
}
return results;

const GEMINI_KEY = 'AIzaSyDGs6effDaTvVzlnxKitiqE366r20lAfQQ';
const item = $input.first().json;

try {
  let fileUri = '';
  let usedVideo = false;
  let usedThumbnails = false;
  let thumbnailBase64List = [];
  let downloadDebug = [];

  // STEP 1: Try to download & upload ACTUAL VIDEO to Gemini
  const streamUrls = item.video_stream_urls || [];
  for (let i = 0; i < Math.min(streamUrls.length, 5); i++) {
    if (usedVideo) break;
    const streamInfo = streamUrls[i];
    try {
      downloadDebug.push('Trying itag=' + streamInfo.itag + ' q=' + streamInfo.quality);
      const videoResp = await this.helpers.httpRequest({
        method: 'GET', url: streamInfo.url, encoding: 'arraybuffer', returnFullResponse: true, timeout: 90000,
        headers: { 'User-Agent': 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.6167.101 Mobile Safari/537.36', 'Accept': '*/*', 'Accept-Encoding': 'identity', 'Range': 'bytes=0-' }
      });
      const videoBuffer = Buffer.from(videoResp.body);
      const videoSizeMB = videoBuffer.length / (1024 * 1024);
      downloadDebug.push('Got ' + videoSizeMB.toFixed(1) + 'MB');
      if (videoSizeMB < 0.05) { downloadDebug.push('Too small'); continue; }
      if (videoSizeMB > 200) { downloadDebug.push('Too large'); continue; }

      const initResp = await this.helpers.httpRequest({
        method: 'POST', url: 'https://generativelanguage.googleapis.com/upload/v1beta/files?key=' + GEMINI_KEY,
        headers: { 'X-Goog-Upload-Protocol': 'resumable', 'X-Goog-Upload-Command': 'start', 'X-Goog-Upload-Header-Content-Length': videoBuffer.length.toString(), 'X-Goog-Upload-Header-Content-Type': 'video/mp4', 'Content-Type': 'application/json' },
        body: JSON.stringify({ file: { displayName: 'src_' + Date.now() + '.mp4' } }), returnFullResponse: true
      });
      const uploadUrl = initResp.headers['x-goog-upload-url'];
      if (!uploadUrl) { downloadDebug.push('No upload URL'); continue; }

      const uploadResp = await this.helpers.httpRequest({
        method: 'POST', url: uploadUrl,
        headers: { 'Content-Length': videoBuffer.length.toString(), 'X-Goog-Upload-Offset': '0', 'X-Goog-Upload-Command': 'upload, finalize' },
        body: videoBuffer, returnFullResponse: true, timeout: 240000
      });
      const fileInfo = typeof uploadResp.body === 'string' ? JSON.parse(uploadResp.body) : uploadResp.body;
      let fileName = fileInfo?.file?.name;
      fileUri = fileInfo?.file?.uri || '';
      let fileState = fileInfo?.file?.state || 'PROCESSING';
      downloadDebug.push('Uploaded, state=' + fileState);

      let pollCount = 0;
      while (fileState === 'PROCESSING' && pollCount < 60) {
        await new Promise(r => setTimeout(r, 5000)); pollCount++;
        const sr = await this.helpers.httpRequest({ method: 'GET', url: 'https://generativelanguage.googleapis.com/v1beta/' + fileName + '?key=' + GEMINI_KEY });
        const sd = typeof sr === 'string' ? JSON.parse(sr) : sr;
        fileState = sd.state; fileUri = sd.uri || fileUri;
      }
      if (fileState === 'ACTIVE' && fileUri) { usedVideo = true; downloadDebug.push('VIDEO READY'); }
      else { downloadDebug.push('Not active: ' + fileState); fileUri = ''; }
    } catch (dlErr) { downloadDebug.push('Fail: ' + dlErr.message.substring(0, 80)); }
  }

  // STEP 2 FALLBACK: Multiple thumbnails
  if (!usedVideo && item.video_id && item.source_type === 'youtube') {
    downloadDebug.push('Trying thumbnails');
    const vid = item.video_id;
    const thumbUrls = [
      'https://img.youtube.com/vi/' + vid + '/maxresdefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/sddefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/hqdefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/1.jpg',
      'https://img.youtube.com/vi/' + vid + '/2.jpg',
      'https://img.youtube.com/vi/' + vid + '/3.jpg'
    ];
    for (const tUrl of thumbUrls) {
      try {
        const tr = await this.helpers.httpRequest({ method: 'GET', url: tUrl, encoding: 'arraybuffer', returnFullResponse: true, timeout: 10000 });
        const buf = Buffer.from(tr.body);
        if (buf.length > 5000) thumbnailBase64List.push(buf.toString('base64'));
      } catch (e) {}
    }
    if (thumbnailBase64List.length > 0) { usedThumbnails = true; downloadDebug.push('Got ' + thumbnailBase64List.length + ' thumbs'); }
  }

  // STEP 3: Call Gemini
  const parts = [];
  if (usedVideo && fileUri) {
    parts.push({ fileData: { mimeType: 'video/mp4', fileUri: fileUri } });
    parts.push({ text: `WATCH THE VIDEO FILE ABOVE carefully. IGNORE the title — it may be misleading. Describe ONLY what you SEE.\n\nTitle (may be wrong): ${item.title || ''}\nDuration: ${item.duration_seconds || 0}s\n\nFor each scene describe: subject appearance (hair, build, skin, clothing), actions, environment, camera work, lighting, colors, mood.\n\nReturn ONLY valid JSON:\n{\n  "scene_count": <n>,\n  "scenes": [{"timestamp":"0-5s","subject_appearance":"exact","clothing":"exact","actions":"exact","setting":"exact","camera":"exact","lighting":"exact","colors":"exact","mood":"exact"}],\n  "overall_style": "visual style",\n  "consistent_elements": "what stays the same",\n  "video_narrative": "visual story start to end"\n}` });
  } else if (usedThumbnails) {
    for (let i = 0; i < Math.min(thumbnailBase64List.length, 5); i++) {
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: thumbnailBase64List[i] } });
    }
    parts.push({ text: `LOOK AT THESE ${Math.min(thumbnailBase64List.length, 5)} IMAGES from a video. TRUST THE IMAGES, not the title.\n\nTitle (may be misleading): ${item.title || ''}\nTranscript: ${(item.transcript || '').substring(0, 1500)}\n\nDescribe what you SEE in each image: subjects, clothing, actions, setting, lighting, colors.\n\nReturn ONLY valid JSON:\n{\n  "scene_count": <n>,\n  "scenes": [{"timestamp":"image 1","subject_appearance":"what you see","clothing":"what you see","actions":"what you see","setting":"what you see","camera":"what you see","lighting":"what you see","colors":"what you see","mood":"what you see"}],\n  "overall_style": "style",\n  "consistent_elements": "consistent",\n  "video_narrative": "narrative"\n}` });
  } else {
    parts.push({ text: `Could not load video. Infer from transcript.\n\nTitle: ${item.title || ''}\nTranscript: ${item.transcript || ''}\n\nReturn ONLY valid JSON:\n{\n  "scene_count": 3,\n  "scenes": [{"timestamp":"inferred","subject_appearance":"inferred","clothing":"inferred","actions":"inferred","setting":"inferred","camera":"inferred","lighting":"inferred","colors":"inferred","mood":"inferred"}],\n  "overall_style": "inferred",\n  "consistent_elements": "inferred",\n  "video_narrative": "inferred"\n}` });
  }

  const sysText = usedVideo
    ? 'You are watching an actual video. Describe ONLY what you see. The title may be misleading — trust your eyes. Be extremely specific about visual details. Output ONLY valid JSON.'
    : usedThumbnails
    ? 'You are looking at actual screenshots from a video. Describe ONLY what you see. Trust the images, not the title. Output ONLY valid JSON.'
    : 'Infer visual content from transcript. Mark as inference. Output ONLY valid JSON.';

  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ contents: [{ role: 'user', parts: parts }], systemInstruction: { parts: [{ text: sysText }] }, generationConfig: { temperature: 0.1 } }),
    timeout: 240000
  });
  const r = typeof resp === 'string' ? JSON.parse(resp) : resp;
  if (r.error) throw new Error('Gemini: ' + JSON.stringify(r.error));
  let aText = r.candidates?.[0]?.content?.parts?.[0]?.text || '';
  aText = aText.replace(/[\x00-\x1F\x7F]/g, ' ');
  let analysis;
  try { analysis = JSON.parse(aText); } catch (e) { const m = aText.match(/\{[\s\S]*\}/); try { analysis = m ? JSON.parse(m[0]) : { overall_style: aText }; } catch (e2) { analysis = { overall_style: aText }; } }
  const method = usedVideo ? 'VIDEO_UPLOADED' : usedThumbnails ? 'MULTI_THUMBNAIL' : 'TEXT_ONLY';

  return [{ json: { source_url: item.source_url, title: item.title, transcript: item.transcript, duration_seconds: item.duration_seconds, aspect_ratio: item.aspect_ratio, source_type: item.source_type, analysis: JSON.stringify(analysis), debug_method: method, debug_details: downloadDebug.join(' | ') } }];
} catch (err) {
  return [{ json: { source_url: item.source_url || '', title: item.title || '', transcript: '', duration_seconds: 0, aspect_ratio: item.aspect_ratio || '16:9', source_type: item.source_type || '', analysis: '{}', debug_method: 'FAILED', debug_details: 'ERROR: ' + err.message } }];
}

const GEMINI_KEY = 'AIzaSyDGs6effDaTvVzlnxKitiqE366r20lAfQQ';
const item = $input.first().json;

try {
  let analysis = {};
  try { analysis = JSON.parse(item.analysis || '{}'); } catch(e) { analysis = { overall_style: item.analysis }; }

  let sceneDetails = '';
  if (analysis.scenes && analysis.scenes.length > 0) {
    sceneDetails = analysis.scenes.map((s, i) => {
      return `Scene ${i+1} (${s.timestamp || ''}):\n  Subject: ${s.subject_appearance || ''}\n  Clothing: ${s.clothing || ''}\n  Actions: ${s.actions || ''}\n  Setting: ${s.setting || ''}\n  Camera: ${s.camera || ''}\n  Lighting: ${s.lighting || ''}\n  Colors: ${s.colors || ''}\n  Mood: ${s.mood || ''}`;
    }).join('\n\n');
  }

  // We need 4 clips x 10s = 40 seconds
  // Generate 4 sequential prompts
  const userText = `VISUAL ANALYSIS OF ORIGINAL VIDEO:\n\n${sceneDetails || item.analysis || 'No analysis'}\n\nStyle: ${analysis.overall_style || 'unknown'}\nConsistent: ${analysis.consistent_elements || 'unknown'}\nNarrative: ${analysis.video_narrative || 'unknown'}\n\nAnalysis method: ${item.debug_method || 'unknown'}\n\n---\n\nWrite exactly 4 sequential video prompts that RECREATE this video\'s visual content. Each prompt = one 10-second clip. The Seedance AI will EXTEND from the last frame of each clip into the next, so they must flow seamlessly.\n\nCRITICAL — MATCH THE ORIGINAL:\n- Recreate the SAME environment, lighting, colors, mood, and actions\n- Base prompts on the SCENE DESCRIPTIONS above (from watching the actual video)\n- Same character throughout all 4 clips\n\nCONNECTED STORY: The 4 clips form ONE continuous narrative featuring both characters. The end of each clip must lead directly into the start of the next. Both characters must be visible and interacting in every clip.\n\nMATCH LOCATIONS FROM THE VIDEO: Recreate the exact settings from the original video. Do not invent locations. If the video stays in one place, vary the area or angle within it. Describe precisely: surfaces, textures, colors, props, lighting, atmosphere.\n\nSTRUCTURE (3-act across 4 clips):\n- Clip 1: Opening — establish BOTH characters together in the video setting, mood and dynamic\n- Clip 2: Interaction develops — follow the video location faithfully\n- Clip 3: Main action between them intensifies\n- Clip 4: The story resolves — final moment\n\nEXTENSION RULES (clips 2-4 extend from previous):\n- Start each prompt describing WHERE the scene picks up from\n- Describe the NEXT action that naturally follows\n- Keep the same character, setting, lighting throughout\n- Gradual progression, not sudden jumps\n\nSAFETY:\n- No real people, celebrities, named individuals\n- No brand names\n- TWO CONSISTENT ASIAN CHARACTERS: There are exactly two characters across ALL 4 clips — one young East Asian WOMAN and one young East Asian MAN. Character A (woman): straight black hair (e.g. shoulder-length bob), warm light skin tone, almond-shaped eyes, specific outfit described in full. Character B (man): short straight dark hair, warm light skin tone, almond-shaped eyes, specific outfit described in full. Both described identically every clip — same hair, clothing, build.\n\nFORMAT:\n- 180-220 words each, one flowing paragraph, no bullet points\n- VIVID CHARACTER DESCRIPTIONS: Describe both characters fully every clip — hair, clothing, expression, posture. Identical across all 4 clips.\n- FILL 10 SECONDS WITH MOVEMENT: Describe a sequence with a clear start, middle, and end. Never a single static pose.\n- CHARACTER MOVEMENT: Both characters actively move — walking, turning, reaching, leaning, stepping back. Neither stands completely still.\n- CAMERA MOVEMENT: Active camera motion every clip — push-in, pull-back reveal, lateral tracking, low-angle rise. Camera never static.\n- DISTINCT CAMERA PER CLIP: One per clip, never repeated — slow push-in, wide pull-back, lateral tracking, low-angle rising.\n- NO DIALOGUE OR TEXT: All emotion through movement and expression.\n- NO timestamps, NO jargon, NO tag lists, NO negative words, NO audio cue mentions\n- End each with: photorealistic, 4K ultra-HD, cinematic lighting, 24fps, subtle film grain, smooth motion blur\n\nReturn ONLY valid JSON:\n{\n  "clip_1_prompt": "opening scene 180-220 words",\n  "clip_2_prompt": "continues from clip 1",\n  "clip_3_prompt": "middle development",\n  "clip_4_prompt": "conclusion",\n  "global_style": "consistent visual style",\n  "character_description": "both characters described"\n}`;

  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ role: 'user', parts: [{ text: userText }] }],
      systemInstruction: { parts: [{ text: 'You write highly detailed cinematic AI video generation prompts telling ONE continuous story across 4 clips. Two characters: a young East Asian woman and a young East Asian man — described identically every clip. Both present and interacting in all 4 clips. Every clip fills 10 seconds with movement — start, middle, end — both characters moving, camera in motion. No dialogue, no text. Match the original video setting, lighting, colors, and mood. Output ONLY valid JSON.' }] },
      generationConfig: { temperature: 0.3 }
    }),
    timeout: 120000
  });

  const r = typeof resp === 'string' ? JSON.parse(resp) : resp;
  if (r.error) throw new Error('Gemini: ' + JSON.stringify(r.error));
  let text = r.candidates?.[0]?.content?.parts?.[0]?.text || '';
  text = text.replace(/[\x00-\x1F\x7F]/g, ' ');
  let parsed;
  try { parsed = JSON.parse(text); } catch (e) { const m = text.match(/\{[\s\S]*\}/); try { parsed = m ? JSON.parse(m[0]) : null; } catch (e2) { parsed = null; } }
  if (!parsed || !parsed.clip_1_prompt) throw new Error('Parse failed: ' + text.substring(0, 300));

  const prompts = [
    parsed.clip_1_prompt || '',
    parsed.clip_2_prompt || '',
    parsed.clip_3_prompt || '',
    parsed.clip_4_prompt || ''
  ];

  return [{ json: {
    source_url: item.source_url || '',
    title: item.title || '',
    aspect_ratio: item.aspect_ratio || '16:9',
    source_type: item.source_type || '',
    all_prompts: JSON.stringify(prompts),
    current_clip: 0,
    total_clips: 4,
    clip_duration: 10,
    last_video_url: '',
    all_video_urls: '[]',
    global_style: parsed.global_style || '',
    character_description: parsed.character_description || '',
    debug_method: item.debug_method || '',
    debug_details: item.debug_details || '',
    poll_count: 0
  } }];
} catch (err) {
  return [{ json: {
    source_url: item.source_url || '', title: item.title || '',
    aspect_ratio: item.aspect_ratio || '16:9', source_type: item.source_type || '',
    all_prompts: '[]', current_clip: 0, total_clips: 0, clip_duration: 10,
    last_video_url: '', all_video_urls: '[]', global_style: '', character_description: '',
    debug_method: 'PROMPT_ERROR', debug_details: err.message
  } }];
}

const SEEDANCE_KEY = 'ark-c43d75c1-1b4f-4039-ade1-810ad5069409-bd5e1';
const SEEDANCE_URL = 'https://ark.ap-southeast.bytepluses.com/api/v3/contents/generations/tasks';
const SEEDANCE_MODEL = 'dreamina-seedance-2-0-260128';

const item = $input.first().json;
const currentClip = Number(item.current_clip) || 0;
const allPrompts = JSON.parse(item.all_prompts || '[]');
const prompt = allPrompts[currentClip] || 'A cinematic scene, photorealistic, 4K, cinematic lighting';
const lastVideoUrl = item.last_video_url || '';
const clipDuration = item.clip_duration || 10;

// Build content array: text prompt + optional video reference for extension
const content = [{ type: 'text', text: prompt }];
if (lastVideoUrl) {
  // This is the EXTEND feature: pass previous video URL so Seedance continues from last frame
  content.push({ type: 'video_url', video_url: { url: lastVideoUrl } });
}

const requestBody = {
  model: SEEDANCE_MODEL,
  content: content,
  duration: clipDuration,
  generate_audio: false,
  watermark: false
};

// Submit the task
try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: SEEDANCE_URL,
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + SEEDANCE_KEY
    },
    body: JSON.stringify(requestBody),
    timeout: 60000
  });

  const resp = typeof response === 'string' ? JSON.parse(response) : response;
  const taskId = resp.id || resp.task_id || '';

  if (!taskId) {
    throw new Error('No task ID returned: ' + JSON.stringify(resp).substring(0, 500));
  }

  return [{ json: {
    task_id: taskId,
    source_url: item.source_url || '',
    title: item.title || '',
    aspect_ratio: item.aspect_ratio || '16:9',
    source_type: item.source_type || '',
    all_prompts: item.all_prompts || '[]',
    current_clip: currentClip,
    total_clips: item.total_clips || 5,
    clip_duration: clipDuration,
    last_video_url: lastVideoUrl,
    all_video_urls: item.all_video_urls || '[]',
    global_style: item.global_style || '',
    character_description: item.character_description || '',
    current_prompt: prompt,
    is_extend: lastVideoUrl ? 'yes' : 'no',
    debug_method: item.debug_method || '',
    debug_details: item.debug_details || '',
    poll_count: 0
  } }];
} catch (err) {
  return [{ json: {
    task_id: '',
    source_url: item.source_url || '',
    title: item.title || '',
    current_clip: currentClip,
    total_clips: item.total_clips || 5,
    all_video_urls: item.all_video_urls || '[]',
    error: 'Seedance submit failed: ' + err.message,
    status: 'submit_failed',
    debug_method: item.debug_method || '',
    debug_details: item.debug_details || ''
  } }];
}

const SEEDANCE_KEY = 'ark-c43d75c1-1b4f-4039-ade1-810ad5069409-bd5e1';
const item = $input.first().json;
const taskId = item.task_id || '';
const pollCount = (Number(item.poll_count) || 0) + 1;

if (!taskId) {
  return [{ json: { ...item, status: 'no_task_id', poll_count: pollCount } }];
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://ark.ap-southeast.bytepluses.com/api/v3/contents/generations/tasks/' + taskId,
    headers: { 'Authorization': 'Bearer ' + SEEDANCE_KEY },
    timeout: 30000
  });

  const resp = typeof response === 'string' ? JSON.parse(response) : response;
  const status = resp.status || 'unknown';

  // Extract video URL if succeeded
  let videoUrl = '';
  if (status === 'succeeded') {
    if (resp.content && typeof resp.content === 'object' && !Array.isArray(resp.content)) {
      videoUrl = resp.content.video_url || resp.content.url || '';
    }
    if (!videoUrl && Array.isArray(resp.content)) {
      for (const c of resp.content) { if (c.video_url) { videoUrl = c.video_url; break; } if (c.url) { videoUrl = c.url; break; } }
    }
    if (!videoUrl && resp.output) videoUrl = resp.output.video_url || resp.output.url || '';
    if (!videoUrl && resp.video_url) videoUrl = resp.video_url;
    if (!videoUrl) {
      const jsonStr = JSON.stringify(resp);
      const urlMatch = jsonStr.match(/"(?:video_url|url|download_url|file_url)":"(https?:\/\/[^"]+)"/i);
      if (urlMatch) videoUrl = urlMatch[1];
    }
  }

  return [{ json: {
    task_id: taskId,
    task_status: status,
    video_url: videoUrl,
    source_url: item.source_url || '',
    title: item.title || '',
    aspect_ratio: item.aspect_ratio || '16:9',
    source_type: item.source_type || '',
    all_prompts: item.all_prompts || '[]',
    current_clip: item.current_clip || 0,
    total_clips: item.total_clips || 5,
    clip_duration: item.clip_duration || 10,
    last_video_url: item.last_video_url || '',
    all_video_urls: item.all_video_urls || '[]',
    global_style: item.global_style || '',
    character_description: item.character_description || '',
    current_prompt: item.current_prompt || '',
    is_extend: item.is_extend || 'no',
    debug_method: item.debug_method || '',
    debug_details: item.debug_details || '',
    poll_count: pollCount,
    raw_status: JSON.stringify(resp).substring(0, 500)
  } }];
} catch (err) {
  return [{ json: { ...item, task_status: 'poll_error', video_url: '', poll_count: pollCount, raw_status: err.message } }];
}

// Clip succeeded! Store the video URL and check if we need more clips
const item = $input.first().json;
const currentClip = Number(item.current_clip) || 0;
const totalClips = Number(item.total_clips) || 5;
const videoUrl = item.video_url || '';

const existingUrls = JSON.parse(item.all_video_urls || '[]');
existingUrls.push(videoUrl);

const nextClip = currentClip + 1;
const needsMore = nextClip < totalClips;

return [{ json: {
  source_url: item.source_url || '',
  title: item.title || '',
  aspect_ratio: item.aspect_ratio || '16:9',
  source_type: item.source_type || '',
  all_prompts: item.all_prompts || '[]',
  current_clip: nextClip,
  total_clips: totalClips,
  clip_duration: item.clip_duration || 10,
  last_video_url: videoUrl,
  all_video_urls: JSON.stringify(existingUrls),
  global_style: item.global_style || '',
  character_description: item.character_description || '',
  needs_more: needsMore,
  debug_method: item.debug_method || '',
  debug_details: item.debug_details || '',
  clip_just_done: currentClip + 1,
  poll_count: 0
} }];
